for (const [lang, faqObj] of Object.entries(FAQS_DATA)) {
  const filePath = path.join(DICT_DIR, `${lang}.json`);
  if (!fs.existsSync(filePath)) {
    console.error(`Missing file: ${filePath}`);
    continue;
  }
  const fileContent = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  fileContent.faq = faqObj;
  fs.writeFileSync(filePath, JSON.stringify(fileContent, null, 2) + '\n', 'utf8');
  console.log(`Updated ${lang}.json successfully with ${Object.keys(faqObj).length} FAQ keys`);
}
